import { useEffect, useState } from 'react';
import { useRouter } from 'next/router';
import Head from 'next/head';
import { getCurrentUser, logout } from '../lib/auth';

export default function AdminPortal() {
  const router = useRouter();
  const [user, setUser] = useState(null);

  useEffect(() => {
    const u = getCurrentUser();
    if (!u || u.role !== 'admin') {
      router.replace('/login');
      return;
    }
    setUser(u);
  }, []);

  if (!user) return null;

  return (
    <>
      <Head><title>Admin Portal</title></Head>
      <div style={{ minHeight: '100vh', background: '#0a0e1a', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: '#fff', fontFamily: 'Inter, sans-serif' }}>
        <div style={{ width: 56, height: 56, borderRadius: 16, background: 'linear-gradient(135deg, #F2A900, #e09800)', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 20 }}>
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#0a0e1a" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
        </div>
        <h1 style={{ fontSize: '1.3rem', fontWeight: 700, marginBottom: 8 }}>Admin Portal</h1>
        <p style={{ color: 'rgba(255,255,255,0.4)', fontSize: '0.9rem', marginBottom: 24 }}>Welcome, {user.firstName} {user.lastName}</p>
        <p style={{ color: 'rgba(255,255,255,0.25)', fontSize: '0.8rem', marginBottom: 32, padding: '12px 20px', background: 'rgba(255,255,255,0.04)', borderRadius: 12, border: '1px solid rgba(255,255,255,0.06)' }}>Full portal coming in Phase 2</p>
        <button onClick={() => { logout(); router.push('/login'); }} style={{ padding: '12px 28px', background: 'rgba(239,68,68,0.15)', border: '1px solid rgba(239,68,68,0.2)', borderRadius: 12, color: '#fca5a5', fontSize: '0.85rem', fontWeight: 600, cursor: 'pointer', transition: 'all 0.2s ease' }}>
          Sign Out
        </button>
      </div>
    </>
  );
}
